ies WHEN LOWER(CATEGORY) LIKE \'%shoe%\' OR LOWER(CATEGORY) LIKE \'%sneaker%\' OR LOWER(CATEGORY) LIKE \'%slipper%\' THEN \'Shoes\' WHEN LOWER(CATEGORY) LIKE \'%sunglass%\' THEN \'Sunglasses\' WHEN LOWER(CATEGORY) LIKE \'%belt%\' THEN \'Belts\' WHEN LOWER(CATEGORY) LIKE \'%bag%\' THEN \'Bags\' WHEN LOWER(CATEGORY) LIKE \'%accessor%\' THEN \'Accessories\' WHEN LOWER(CATEGORY) LIKE \'%perfume%\' OR LOWER(CATEGORY) LIKE \'%fragrance%\' THEN \'Perfumes\' ELSE category END ) AS cleaned_category FROM snitch_db.maplemonk.gs_product_tracking_new_main WHERE sku_status_ not in (\'Delivered\', \'Cancel\', \'Hold\') ), b as ( select sku, online_qty, expected_delivery_date FDD, lower(replace(Description, \'-\', \'\')) category from snitch_db.maplemonk.gs_onlinegoods_rts where ( TO_DATE(expected_delivery_date, \'DD/MM/YYYY\') > CURRENT_DATE() -4 or expected_delivery_date is null ) ), sold as ( select Distinct SKU_Group from snitch_db.maplemonk.category_journey where sku_group like \'4%\' ), c as ( select sku, qty, ifnull(FDD, \'No Date mentioned\') FDD, category, status from ( select normalized_sku sku, Proj_qty qty, FDD, cleaned_category category, sku_status_ status from a where normalized_sku not in ( select sku from b where sku not in ( select SKU_Group from sold ) ) union all select sku, online_qty qty, FDD, category, \'RTS\' status from b ) ), COGS AS ( SELECT sku_group, MAX(cp) AS cost_price FROM ( SELECT DISTINCT sku_group, cp FROM snitch_db.maplemonk.PURCHASE_ORDER_JOURNEY WHERE NULLIF(sku_group, \'\') IS NOT NULL UNION ALL SELECT CONCAT( SPLIT_PART(sku, \'-\', 1), \'-\', SPLIT_PART(sku, \'-\', 2) ) AS sku_group, MAX(cost_price) AS cp FROM snitch_db.maplemonk.UC_FINAL_ITEM_MASTER GROUP BY 1 ) AS combined_data GROUP BY sku_group ), d as ( SELECT sku, FDD, Qty, c.status, lower(replace(ifnull(c.category, b.category), \'-\', \'\')) Category, print_design_mapped, CASE WHEN s.sku_group IS NOT NULL THEN \'Repeat\' ELSE \'New\' END AS Remarks, cost_price COGS from c left join snitch_db.maplemonk.metafields_data b on c.sku = b.sku_group left join cogs on c.sku = cogs.sku_group LEFT JOIN sold s ON c.sku = s.sku_group ), e as ( select category, round(avg(cogs), 0) avg_cogs from d where cogs is not null group by 1 ), inwards_expected as ( select sku, FDD, qty, status, d.category, remarks, ifnull(cogs, avg_cogs) cogs_final, ifnull(cogs, avg_cogs) * qty COGS_value,CASE WHEN FDD = \'No Date mentioned\' THEN \'No Date mentioned\' when FDD is not null then TO_VARCHAR( DATE_TRUNC( \'MONTH\', TRY_TO_DATE(FDD, \'DD/MM/YYYY\') ), \'YYYY-MM\' ) ELSE \'Other\' END AS FDD_MONTH, CASE WHEN LOWER(sku) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(sku) LIKE \'r4mbg%\' THEN \'plus_size\' -- WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' -- WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' -- WHEN LOWER(b.category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MLRT%\' THEN \'luxe\' WHEN UPPER(sku) LIKE \'4MLXT%\' THEN \'luxe\' WHEN UPPER(sku) LIKE \'4MLXD%\' THEN \'luxe\' WHEN UPPER(sku) LIKE \'4MTLD%\' THEN \'luxe\' WHEN UPPER(sku) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MSFC%\' THEN \'long_tail\' else \'Snitch\' end L1_Category from d left join e on d.category = e.category ), f as ( select sku, L1_Category, category, FDD_month, COGS_value, qty from inwards_expected ), putaway_report as ( SELECT upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_group, TO_VARCHAR( DATE_TRUNC(\'MONTH\', \"PUTAWAY_UPDATED\"::DATE), \'YYYY-MM\' ) AS Month, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS Qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\" >= DATE \'2026-01-01\' AND LOWER(FINAL_TYPE) = \'new inward\' GROUP BY 1, 2 ), inwarded as ( select ff.SKU_group,CASE WHEN LOWER(ff.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(ff.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MLRT%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MLXT%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MLXD%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MTLD%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'long_tail\' else \'Snitch\' end L1_Category, lower( replace( ifnull( a.category,case WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'