nts\' WHEN UPPER(ff.sku_group) LIKE \'4MSC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSK%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MSD%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSH%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSP%\' THEN \'Pyjamas\' WHEN UPPER(ff.sku_group) LIKE \'4MSWH%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWS%\' THEN \'Sweatshirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSW%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MTP%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MSJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(ff.sku_group) LIKE \'4MST%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(ff.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'Belts\' WHEN UPPER(ff.sku_group) LIKE \'4MLX%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MPL%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'Accessories\' end ), \'-\', \'\' ) ) Category, Month, Qty, Qty * cost_price inward_value from putaway_report ff left join cogs b on ff.sku_group = b.sku_group left join snitch_db.maplemonk.metafields_data a on ff.sku_group = a.sku_group ), inv as ( WITH warehouse AS ( SELECT \"FACILITY\", UPPER( TRIM( REGEXP_REPLACE(\"Item SkuCode\"::STRING, \'-[^-]+$\', \'\') ) ) AS sku_group, \"Category Name\", SUM(\"INVENTORY\") AS \"Available\", SUM(\"Inventory Blocked\") AS \"Blocked\", SUM(TRY_TO_NUMBER(\"Not Found\")) AS \"Not Found\", SUM(\"Putaway Pending\") AS \"Putaway Pending\", SUM(\"Putback Pending\") AS \"Putback Pending\", SUM(\"Bad Inventory\") AS \"Bad Inventory\", SUM(\"Inventory Not Synced\") AS \"Not Synced\", SUM(\"Stock In Transfer\") AS \"Stock Transfer\" FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE \"FACILITY\" IN ( \'SAPL_EMIZA\', \'SAPL-WH1\', \'SAPL-WH2\', \'SAPL-NORTH-TAURU\' ) AND \"DATE\" = CAST(DATEADD(HOUR, 7, CURRENT_TIMESTAMP()) AS DATE) GROUP BY \"FACILITY\", UPPER( TRIM( REGEXP_REPLACE(\"Item SkuCode\"::STRING, \'-[^-]+$\', \'\') ) ), \"Category Name\" ), -- Offline/JIT quantities by sku_group offline_inv AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, SUM(inventory) AS available_inv, SUM(jit_qty) AS jit_inv FROM snitch_db.maplemonk.offline_master GROUP BY 1 ), -- Cost per sku_group COGS AS ( SELECT sku_group, MAX(cp) AS cost_price FROM ( SELECT DISTINCT sku_group, cp FROM snitch_db.maplemonk.PURCHASE_ORDER_JOURNEY WHERE NULLIF(sku_group, \'\') IS NOT NULL UNION ALL SELECT CONCAT( SPLIT_PART(sku, \'-\', 1), \'-\', SPLIT_PART(sku, \'-\', 2) ) AS sku_group, MAX(cost_price) AS cp FROM snitch_db.maplemonk.UC_FINAL_ITEM_MASTER GROUP BY 1 ) AS combined_data GROUP BY sku_group ), -- Optional mapping to get a canonical category per sku_group (from WH data) sku_group_category AS ( SELECT sku_group, MAX(\"Category Name\") AS category_name FROM warehouse GROUP BY 1 ), -- Warehouse rollup by sku_group (qty + COGS per bucket) wh_rollup_sku AS ( SELECT a.sku_group, MAX(a.\"Category Name\") AS category_name, -- Quantities SUM(a.\"Available\") AS qty_available, SUM(a.\"Blocked\") AS qty_blocked, SUM(a.\"Not Found\") AS qty_not_found, SUM(a.\"Bad Inventory\") AS qty_bad_inventory, SUM(a.\"Not Synced\") AS qty_not_synced, SUM(a.\"Putaway Pending\") AS qty_putaway_pending, SUM(a.\"Putback Pending\") AS qty_putback_pending, SUM(a.\"Stock Transfer\") AS qty_stock_transfer, -- COGS per bucket SUM(a.\"Available\" * COALESCE(b.cost_price, 0)) AS available_cogs, SUM(a.\"Blocked\" * COALESCE(b.cost_price, 0)) AS blocked_cogs, SUM(a.\"Not Found\" * COALESCE(b.cost_price, 0)) AS not_found_cogs, SUM(a.\"Bad Inventory\" * COALESCE(b.cost_price, 0)) AS bad_inventory_cogs, SUM(a.\"Not Synced\" * COALESCE(b.cost_price, 0)) AS not_synced_cogs, SUM(a.\"Putaway Pending\" * COALESCE(b.cost_price, 0)) AS putaway_pending_cogs, SUM(a.\"Putback Pending\" * COALESCE(b.cost_price, 0)) AS putback_pending_cogs, SUM(a.\"Stock Transfer\" * COALESCE(b.cost_price, 0)) AS stock_transfer_cogs, -- Total COGS across all buckets SUM( ( a.\"Available\" + a.\"Blocked\" + a.\"Not Found\" + a.\"Bad Inventory\" + a.\"Not Synced\" + a.\"Putaway Pending\" + a.\"Putback Pending\" + a.\"Stock Transfer\" ) * COALESCE(b.cost_price, 0) ) AS total_cogs FROM warehouse a LEFT JOIN cogs b ON a.sku_group = b.sku_group GROUP BY a.sku_group ), -- Offline/JIT rollup by sku_group (qty + COGS) offline_rollup_sku AS ( SELECT oi.sku_group, SUM(oi.available_inv) AS qty_offline_available, SUM(oi.available_inv * COALESCE(c.cost_price, 0)) AS offline_available_cogs, SUM(oi.jit_inv) AS qty_jit, SUM(oi.jit_inv * COALESCE(c.cost_price, 0)) AS jit_cogs FROM offline_inv oi LEFT JOIN cogs c ON oi.sku_group = c.sku_group GROUP BY oi.sku_group ), -- MP metrics per sku_group mp AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(days_since_inward) AS days_since_inward, SUM(mp_quant30) AS mp_quant_30 FROM snitch_db.maplemonk.category_journey GROUP BY 1 ), ff as ( SELECT COALESCE(w.sku_group, o.sku_group) AS sku_group, -- Best-effort readable Category label (keeps your renaming rules) CASE WHEN COALESCE(w.category_name, sgc.category_name) IN (\'Sweater\') THEN \'Sweaters\' WHEN COALESCE(w.category_name, sgc.category_name) = \'Footwear\' THEN \'Shoes\' WHEN COALESCE(w.category_name, sgc.category_name) = \'JOGGERS\' THEN \'Joggers & Trackpants\' WHEN COALESCE(w.category_name, sgc.category_name) = \'Jacket\' THEN \'Jackets\' WHEN COALESCE(w.category_name, sgc.category_name) = \'Trouser\' THEN \'Trousers\' WHEN COALESCE(w.category_name, sgc.category_name) = \'PYJAMAS\' THEN \'Night Suit & Pyjamas\' ELSE COALESCE(w.category_name, sgc.category_name) END AS \"Category Name\", -- Warehouse quantities w.qty_available, w.qty_blocked, w.qty_not_found, w.qty_bad_inventory, w.qty_not_synced, w.qty_putaway_pending,