d \'2025-12-31\' THEN gross_quantity::int ELSE 0 END ) dec_Sales_qty, FROM snitch_db.maplemonk.horizontal_sales_categories left join sku_cogs using(sku_group) GROUP BY 1, 2 ), sales_mix as ( WITH base_sales AS ( -- Shopify + Marketplace SELECT date, sku_group, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' when type = \'Store\' then \'Offline\' END AS channel, gross_sales::INT * 0.75 AS qty, gross_quantity::int * cogs * 0.75 cogs_value, FROM snitch_db.maplemonk.horizontal_sales_categories left join sku_cogs using(sku_group) ), sku_monthly AS ( SELECT sku_group, SUM( CASE WHEN date between \'2025-12-01\' and \'2025-12-31\' THEN cogs_value ELSE 0 END ) AS Dec_25_Sales, SUM( CASE WHEN date between \'2024-12-01\' and \'2024-12-31\' THEN qty ELSE 0 END ) AS Dec_Sales, SUM( CASE WHEN date between \'2025-01-01\' and \'2025-01-31\' THEN qty ELSE 0 END ) AS Jan_Sales, SUM( CASE WHEN date between \'2025-02-01\' and \'2025-02-28\' THEN qty ELSE 0 END ) AS feb_Sales, SUM( CASE WHEN date between \'2025-03-01\' and \'2025-03-31\' THEN qty ELSE 0 END ) AS mar_Sales, SUM( CASE WHEN date between current_date() -30 and current_date() THEN qty ELSE 0 END ) AS L30D_Sales, FROM base_sales GROUP BY sku_group ), cte as ( select lower( replace( ifnull( a.category,case WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' when upper(ff.sku_group) like \'4MSN%\' THEN \'Shirts\' when upper(ff.sku_group) like \'4MCR1004%\' then \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MCSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MTR0123%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSWHC%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWC%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MSKC%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MCRD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MCRT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MTLX%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MLRT%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MSC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSK%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MSD%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSH%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSP%\' THEN \'Pyjamas\' WHEN UPPER(ff.sku_group) LIKE \'4MSWH%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWS%\' THEN \'Sweatshirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSW%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MTP%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MSJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(ff.sku_group) LIKE \'4MST%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(ff.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'Belts\' WHEN UPPER(ff.sku_group) LIKE \'4MLX%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MPL%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'Accessories\' end ), \'-\', \'\' ) ) Category, CASE WHEN LOWER(ff.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(ff.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MLRT%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MLXT%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MLXD%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MTLD%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'long_tail\' else \'Snitch\' end L1_Category, -- ff.* -- sum(shopify_sales) shopify_sales, sum(mp_sales) mp_sales, sum(offline_sales) offline_sales, sum(Dec_Sales) * 0.75 Dec_Sales, sum(jan_sales) * 0.75 jan_sales, sum(feb_sales) * 0.75 feb_sales, sum(mar_sales) * 0.75 mar_sales, sum(L30D_Sales) * 0.75 L30D_Sales, sum(Dec_25_Sales) * 0.75 Dec_25_Sales, sum(Dec_25_Sales) Dec_25_Sales_2, sum(jan_sales) / nullif(sum(Dec_Sales), 0) Jan_Factor, sum(feb_sales) / nullif(sum(Dec_Sales), 0) feb_Factor, sum(mar_sales) / nullif(sum(Dec_Sales), 0) mar_Factor from sku_monthly ff left join snitch_db.maplemonk.metafields_data a on ff.sku_group = a.sku_group group by 1, 2 order by 1 ) select L1_Category, category, concat(L1_Category, Category) con, Dec_25_Sales / 10000000, case when l1_category = \'long_tail\' then least(1, Jan_Factor) else Jan_Factor end jan_factor, case when l1_category = \'long_tail\' then least(1, feb_Factor) else feb_Factor end feb_factor, case when l1_category = \'long_tail\' or L1_Category = \'plus_size\' then least(1, mar_Factor) else mar_Factor end mar_factor, case when l1_category = \'long_tail\' then least(1, Jan_Factor) else Jan_Factor end * Dec_25_Sales jan_26_pred, case when l1_category = \'long_tail\' then least(1, feb_Factor) else feb_Factor end * Dec_25_Sales feb_26_pred, case when l1_category = \'long_tail\' or L1_Category = \'plus_size\' then least(1, mar_Factor) else mar_Factor end * Dec_25_Sales mar_26_pred, L30D_Sales / sum(L30D_Sales) over() Sales_mix, Dec_25_Sales_2 / 10000000, from cte ), sales_pred as ( select L1_Category, category, con, ifnull(inv_mix, 0) inv_mix, ifnull(Sales_mix, 0) Sales_mix, sum(jan_26_pred) over() * ( ifnull(inv_mix, 0) * 0.25 + ifnull(Sales_mix, 0) * 0.25 + ifnull( Jan_Factor / nullif(sum(Jan_Factor) over(), 0), 0 ) *.50 ) Jan_26_pred, sum(Feb_26_pred) over() *( ifnull(inv_mix, 0) * 0.25 + ifnull(Sales_mix, 0) * 0.25 + ifnull( feb_Factor / nullif(sum(feb_Factor) over(), 0), 0 ) *.50 ) Feb_26_pred, sum(Mar_26_pred) over() *( ifnull(inv_mix, 0) * 0.25 + ifnull(Sales_mix, 0) * 0.25 + ifnull( mar_Factor / nullif(sum(mar_Factor) over(), 0), 0 ) *.50 ) Mar_26_pred, from inv_mix a full outer join sales_mix b using(con, L1_Category, category) ), sales_pred_pivot as ( SELECT L1_Category, Category, month_col, CASE lower(month_col) WHEN \'jan_26_pred\' THEN \'2026-01\' WHEN \'feb_26_pred\' THEN \'2026-02\' WHEN \'mar_26_pred\' THEN \'2026-03\' END AS Month, round(pred_value / 10000000, 1) pred_value, Sales_mix, inv_mix FROM sales_pred UNPIVOT ( pred_value FOR month_col IN (Jan_26_pred, Feb_26_pred, Mar_26_pred) ) ), months AS ( SELECT TO_VARCHAR( DATEADD(month, seq4(), \'2025-11-01\'::date), \'YYYY-MM\' ) AS month FROM TABLE(GENERATOR(ROWCOUNT => 8)) ), sku_month AS ( SELECT distinct s.SKU_group, min(s.L1_Category) L1_Category, min(s.Category) Category, m.month FROM sku_master s CROSS JOIN months m group by 1, 4 ), final_report AS ( SELECT distinct sm.month, sm.SKU_group, sm.L1_Category, case when sm.Category = \'shirt\' then \'shirts\' when sm.Category = \'sweater\' then \'sweaters\' when sm.Category = \'cargo\' then \'cargo pants\' when sm.Category = \'tshirt\' then \'tshirts\' when sm.Category = \'denim\' or sm.Category like \'chino%\' then \'jeans\' else sm.Category end category, /* Inwards Expected */ IFNULL(ie.qty, 0) AS inward_expected_qty, IFNULL(ie.COGS_value, 0) AS inward_expected_cogs, /* Inwarded */ IFNULL(iw.qty, 0) AS inwarded_qty, IFNULL(iw.inward_value, 0) AS inwarded_cogs, -- CASE -- WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(s.Shopify_MTD, 0) + IFNULL(s.MP_MTD, 0) + IFNULL(s.store_MTD, 0) * cogs.cost_price -- ELSE 0 -- END AS sales_mtd_qty, -- CASE -- WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(s.Shopify_L30D, 0) + IFNULL(s.MP_L30D, 0) + IFNULL(s.store_L30D, 0) * cogs.cost_price -- ELSE 0 -- END AS sales_l30d_qty, /* Inventory — only current month */ CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.Total_cogs, 0) END AS inventory_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.putaway_pending_cogs, 0) END AS putaway_pending_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.putback_pending_cogs, 0) END AS putback_pending_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.qty_offline_available, 0) END AS qty_offline_available, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.offline_available_cogs, 0) END AS offline_available_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.qty_available, 0) END AS WH_available, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.WH_cogs, 0) END AS WH_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.jit_cogs, 0) END AS jit_cogs FROM sku_month sm /* Inwards Expected */ LEFT JOIN ( select sku, fdd_month, sum(qty) qty, sum(COGS_value) COGS_value from inwards_expected group by 1, 2 ) ie ON ie.sku = sm.SKU_group AND ie.FDD_MONTH = sm.month /* Inwarded */ LEFT JOIN inwarded iw ON iw.SKU_group = sm.SKU_group AND iw.month = sm.month /* Sales (no month join) */ LEFT JOIN sales s ON s.SKU_group = sm.SKU_group /* Inventory snapshot (current only) */ LEFT JOIN inv ON inv.SKU_group = sm.SKU_group left join cogs on s.SKU_group = cogs.sku_group ), final_wait as ( select month, L1_Category, category, round( sum( ifnull(offline_available_cogs, 0) + ifnull(WH_cogs, 0) + ifnull(jit_cogs, 0) ) / 10000000, 5 ) opening_inventory_cogs, -- round(sum(ifnull(L30D_Sales,0)) / 10000000, 1) Sales_L30D_cogs, -- round(sum(ifnull(MTD_Sales,0)) / 10000000, 1) Sales_MTD_cogs, round(sum(inwarded_cogs) / 10000000, 1) Inwarded, round(sum(Inward_expected_cogs) / 10000000, 1) Inward_expected_cogs, round(sum(putaway_pending_cogs) / 10000000, 1) putaway_pending_cogs, round(sum(putback_pending_cogs) / 10000000, 1) putback_pending_cogs, sum(qty_offline_available) qty_offline_available, round(sum(offline_available_cogs) / 10000000, 5) offline_available_cogs, sum(WH_available) WH_available, round(sum(WH_cogs) / 10000000, 5) WH_cogs, round(sum(jit_cogs) / 10000000, 5) jit_cogs, from final_report -- where SKU_Group=\'4MST2189-02\' -- left join sales_data using(L1_Category,category) group by 1, 2, 3 order by 1, 2, 3 ), final_base as ( select L1_Category, category, Month, opening_inventory_cogs, -- Sales_MTD_cogs, Inwarded, pred_value, 0 inwards_expected, Inward_expected_cogs, round( case when TO_DATE(month || \'-01\', \'YYYY-MM-DD\') = DATE_TRUNC( \'MONTH\', current_date() ) then MTD_Sales end / 10000000, 1 ) Sales_MTD_cogs, round( case when TO_DATE(month || \'-01\', \'YYYY-MM-DD\') = DATE_TRUNC( \'MONTH\', current_date() ) then L30D_Sales end / 10000000, 1 ) Sales_L30D_cogs from final_wait left join sales_pred_pivot using(L1_Category, category, month) left join sales_data using(L1_Category, category) ), base_1 as ( SELECT L1_Category, category, TO_DATE(month || \'-01\', \'YYYY-MM-DD\') AS month_dt, case when TO_DATE(month || \'-01\', \'YYYY-MM-DD\') = DATE_TRUNC( \'MONTH\', current_date() ) then opening_inventory_cogs + Sales_MTD_cogs - Inwarded else null end current_opening_cogs, COALESCE(inwards_expected, 0) - COALESCE(pred_value, 0) AS net_adj, opening_inventory_cogs, Sales_MTD_cogs, Inwarded, pred_value, inwards_expected, Inward_expected_cogs, Sales_L30D_cogs FROM final_base ), e_anchor AS ( SELECT *, LAST_VALUE(current_opening_cogs IGNORE NULLS) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS base_current_opening_cogs FROM base_1 ), running_adj AS ( SELECT *, SUM(net_adj) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_adj FROM e_anchor ), base_month_adj AS ( SELECT *, SUM(net_adj) OVER ( PARTITION BY L1_Category, category, base_current_opening_cogs ORDER BY month_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS base_adj FROM running_adj ), final_final as( SELECT a.L1_Category, a.category, TO_VARCHAR(month_dt, \'YYYY-MM\') AS month, current_opening_cogs, current_opening_cogs * 30 / nullif(Sales_L30D_cogs, 0) Current_DOI, greatest(0, base_current_opening_cogs + cum_adj) AS Closing_Cogs, greatest(0, base_current_opening_cogs + cum_adj) * 30 / nullif(pred_value, 0) Closing_DOI, BASE_current_opening_cogs, opening_inventory_cogs, Sales_MTD_cogs, Inwarded, pred_value Sales_Pred, inwards_expected, Inward_expected_cogs, cum_adj, base_adj, Sales_L30D_cogs, inwarded_target_set::float INWARDED_TARGET_full_month, CASE WHEN month_dt < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN inwarded_target_set::float WHEN month_dt = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN inwarded_target_set::float * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())) ELSE 0 END AS Inward_TD_target, -- CASE -- WHEN month_dt < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN Sales_Pred -- WHEN month_dt = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN Sales_Pred * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())) -- ELSE 0 -- END AS Sales_Pred_TD_target FROM base_month_adj a left join snitch_db.maplemonk.inwards_target_sheet b on TO_VARCHAR(month_dt, \'YYYY-MM\') = b.month and a.category = b.category and a.l1_category = b.l_1_category where TO_VARCHAR(month_dt, \'YYYY-MM\') in (\'2026-01\', \'2026-02\', \'2026-03\') -- group by 1 ) select L1_Category, category, month, opening_inventory_cogs current_inventory_cogs, opening_inventory_cogs / nullif(Sales_L30D_cogs, 0) Current_DOI, current_opening_cogs current_Months_Opening_cogs, Sales_Pred, Sales_MTD_cogs, -- Sales_Pred_TD_target inwarded, INWARDED_TARGET_full_month, Inward_TD_target, inwarded - Inward_TD_target delta_TD, inwarded - INWARDED_TARGET_full_month delta_full_month, greatest( 0, current_opening_cogs - Sales_Pred + INWARDED_TARGET_full_month ) Closing, greatest( 0, current_opening_cogs - Sales_Pred + INWARDED_TARGET_full_month )*30 / nullif(Sales_Pred, 0) CLosing_DOI from final_final order by 1,2,3;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

